import {editorStyles} from './visual-editor.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function openOverview({api,sb,host,editor,status,isCurrent,onNavigate}){
 editorStyles();editor.replaceChildren();
 const [enquiries,drafts,revisions,audit,...counts]=await Promise.all([all('elan_enquiries'),sb.from('elan_page_drafts').select('page,changes,updated_at'),sb.from('elan_page_revisions').select('page,created_at').order('created_at',{ascending:false}).limit(8),api('admin-list',{table:'elan_audit',offset:0}),...['elan_guests','elan_media','elan_stories','elan_announcements','elan_schedule'].map(async table=>table==='elan_stories'?sb.from(table).select('*',{count:'exact',head:true}).eq('published',false):({count:(await all(table)).filter(r=>!r.published&&!/^site-(slot|image):/.test(r.credit||'')).length}))]);
 for(const r of [drafts,revisions,...counts])if(r.error)throw r.error;if(!isCurrent())return;
 async function all(table){let rows=[],offset=0;while(true){const r=await api('admin-list',{table,offset});rows.push(...r.rows);offset+=50;if(offset>=r.total)return rows;}}
 const pending=drafts.data.filter(d=>d.changes.length),unpublished=counts.reduce((n,c)=>n+c.count,0),newEnquiries=enquiries.filter(r=>r.status==='new').length;
 host.innerHTML=`<section class="app-card"><p class="app-badge">YOUR ÉLAN DESK</p><h2>What needs your attention?</h2><div class="admin-metrics"><div><strong>${newEnquiries}</strong><span>New enquiries</span></div><div><strong>${pending.length}</strong><span>Page drafts</span></div><div><strong>${unpublished}</strong><span>Unpublished entries</span></div></div><div class="app-actions"><button data-go="oc_roster">Add or edit OC members</button><a href="/organisers.html">Open organiser panel ↗</a><button data-go="organiser_inbox">Organiser inbox</button><button data-go="collection_history">Content history</button><button data-go="visitor_insights">Visitor measurement</button><button data-go="visual_editor">Edit website</button><button data-go="elan_media">Manage gallery</button><button data-go="media_library">Photo library</button></div></section><section class="app-card"><h2>Enquiries</h2><p>Search all ${enquiries.length} enquiries. Submitted interest forms appear here too.</p><div class="overview-filters"><label>Search<input id="overview-search" type="search" placeholder="Name, email, school or message"></label><label>Status<select id="overview-status"><option value="">All statuses</option><option value="new">New</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option></select></label><label>Type<select id="overview-kind"><option value="">All types</option><option value="interest">Second edition interest</option><option value="contact">Contact</option><option value="school">Schools</option><option value="volunteer">Volunteering</option></select></label></div><p id="overview-count" role="status"></p><div id="overview-enquiries"></div></section><section class="app-card"><h2>Drafts waiting for you</h2><ul>${pending.map(d=>`<li>${esc(d.page)} · ${d.changes.length} changes · ${new Date(d.updated_at).toLocaleDateString()}</li>`).join('')||'<li>No unpublished page changes.</li>'}</ul><p>Open Edit website and select the page to review its draft.</p><div class="app-actions">${['Guests','Gallery','Stories & film','Announcements','Programme'].map((name,i)=>`<button class="secondary" data-go="${['elan_guests','elan_media','stories_editor','elan_announcements','elan_schedule'][i]}">${name}: ${counts[i].count} unpublished</button>`).join('')}</div></section><section class="app-card"><h2>Recent changes</h2><ul>${[...revisions.data.map(r=>({action:'Page published: '+r.page,created_at:r.created_at})),...audit.rows.slice(0,8)].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,10).map(r=>`<li>${esc(r.action)} <small>${new Date(r.created_at).toLocaleString()}</small></li>`).join('')||'<li>No recent activity.</li>'}</ul><button class="secondary" data-go="elan_audit">Full activity log</button></section>`;
 const q=s=>host.querySelector(s);let page=0;
 function draw(){const term=q('#overview-search').value.toLowerCase(),filter=q('#overview-status').value,kind=q('#overview-kind').value,matches=enquiries.filter(r=>(!filter||r.status===filter)&&(!kind||(kind==='interest'?r.details?.intent==='next-edition':r.kind===kind&&r.details?.intent!=='next-edition'))&&JSON.stringify([r.full_name,r.email,r.details]).toLowerCase().includes(term));const max=Math.max(0,Math.ceil(matches.length/20)-1);page=Math.min(page,max);q('#overview-count').textContent=matches.length+' matching enquiries';q('#overview-enquiries').innerHTML=matches.slice(page*20,page*20+20).map(r=>`<article class="overview-enquiry"><div><span class="app-badge">${r.details?.intent==='next-edition'?'SECOND EDITION INTEREST':esc(r.kind)}</span><h3>${esc(r.full_name)}</h3><a href="mailto:${esc(r.email)}">${esc(r.email)}</a><p>${new Date(r.created_at).toLocaleString()}</p><details><summary>Read enquiry</summary>${Object.entries(r.details||{}).map(([k,v])=>`<p><strong>${esc(k.replaceAll('_',' '))}</strong>: ${esc(v)}</p>`).join('')}<small>Reference: ${esc(r.id)}</small></details></div><form data-enquiry="${esc(r.id)}"><label>Status<select name="status">${['new','in_progress','resolved'].map(v=>`<option value="${v}" ${r.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label><button type="submit">Save status</button><p role="status"></p></form></article>`).join('')||'<p>No enquiries match these filters.</p>';
 if(matches.length>20){const nav=document.createElement('div');nav.className='app-actions';nav.innerHTML=`<button ${page===0?'disabled':''}>Previous</button><span>Page ${page+1} of ${max+1}</span><button ${page===max?'disabled':''}>Next</button>`;nav.firstElementChild.onclick=()=>{page--;draw();};nav.lastElementChild.onclick=()=>{page++;draw();};q('#overview-enquiries').append(nav);}
 for(const form of host.querySelectorAll('[data-enquiry]'))form.onsubmit=async e=>{e.preventDefault();form.inert=true;try{await api('enquiry-status',{id:form.dataset.enquiry,status:form.elements.namedItem('status').value});enquiries.find(r=>r.id===form.dataset.enquiry).status=form.elements.namedItem('status').value;form.querySelector('[role=status]').textContent='Saved.';host.querySelector('.admin-metrics strong').textContent=enquiries.filter(r=>r.status==='new').length;}catch(err){form.querySelector('[role=status]').textContent=err.message;}finally{form.inert=false;}};
 }
 for(const input of host.querySelectorAll('.overview-filters input,.overview-filters select'))input.oninput=()=>{page=0;draw();};for(const b of host.querySelectorAll('[data-go]'))b.onclick=()=>onNavigate(b.dataset.go);draw();status('');
}
